/**
 * Normalizes vocabulary search string for exact key matching
 */
export function normalizeVocabKey(word: string): string {
  if (!word) return '';
  return word
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, ' ');
}

/**
 * Retrieves the comprehensive visual metadata for any vocabulary word.
 * Guarantees exact matching, 100% collision-free authentic photography,
 * and neutral educational placeholders for abstract / pending terms.
 */
export function getVocabularyVisual(
  word: string,
  preferredCategory: 'landmark' | 'geography' | 'food' | 'culture' | 'wildlife' | 'nature' | 'architecture' | 'abstract' = 'landmark',
  customFallbackImage?: string
): VocabularyVisualMetadata {
  const key = normalizeVocabKey(word);

  // 1. Direct exact registry match
  if (VOCABULARY_VISUALS_REGISTRY[key]) {
    const item = VOCABULARY_VISUALS_REGISTRY[key];
    if (customFallbackImage && item.isPlaceholder) {
      return {
        ...item,
        imageUrl: customFallbackImage,
        thumbnailUrl: customFallbackImage,
        isPlaceholder: false
      };
    }
    return item;
  }

  // 2. Fallback when word is completely unregistered
  // Returns clean neutral placeholder object with isPlaceholder: true
  return {
    word: word,
    normalizedKey: key,
    imageUrl: customFallbackImage || '',
    thumbnailUrl: customFallbackImage || '',
    captionEn: `Educational visual coming soon for ${word}.`,
    captionVi: `Hình ảnh giáo dục cho từ "${word}" đang được cập nhật.`,
    author: 'VietDiscovery Curriculum Team',
    source: 'VietDiscovery Educational Archive',
    license: 'Educational Standard License',
    attributionText: 'VietDiscovery by Ms. Trang',
    category: preferredCategory,
    ukIpa: '',
    usIpa: '',
    britishAudioPrompt: `${word}.`,
    exampleSentenceEn: `The word "${word}" is part of VietDiscovery primary English curriculum.`,
    exampleSentenceVi: `Từ vựng "${word}" thuộc chương trình tiếng Anh tiểu học VietDiscovery.`,
    vietnameseMeaning: '',
    educationalContextNote: 'Pending verified photograph.',
    isPlaceholder: !customFallbackImage
  };
}
